import json
import sys
from pathlib import Path

TARGET_EVENTS = {"ModifySnapshotAttribute", "ModifyImageAttribute"}

def find_external_shares(trail_path: str, owned_accounts: set[str]) -> list[dict]:
    doc = json.loads(Path(trail_path).read_text(encoding="utf-8"))
    hits = []
    for rec in doc.get("Records", []):
        ev = rec.get("eventName")
        if ev not in TARGET_EVENTS or rec.get("errorCode"):
            continue
        params = rec.get("requestParameters") or {}
        perm = (params.get("createVolumePermission") or params.get("launchPermission") or {}).get("add", {})
        items = perm.get("items", [])
        for item in items:
            uid = item.get("userId")
            grp = item.get("group")
            if grp == "all" or (uid and uid not in owned_accounts):
                hits.append({
                    "eventTime": rec.get("eventTime"),
                    "eventName": ev,
                    "actorArn": (rec.get("userIdentity") or {}).get("arn"),
                    "resourceId": params.get("snapshotId") or params.get("imageId"),
                    "sharedWith": grp or uid,
                })
    return hits

if __name__ == "__main__":
    allowed = set(sys.argv[2].split(",")) if len(sys.argv) > 2 else set()
    print(json.dumps(find_external_shares(sys.argv[1], allowed), indent=2))
