import json
import sys
from pathlib import Path

def audit_podlist(json_path: str) -> list[dict]:
    data = json.loads(Path(json_path).read_text(encoding="utf-8"))
    findings = []
    for item in data.get("items", []):
        meta = item.get("metadata") or {}
        spec = item.get("spec") or {}
        pod_ref = f"{meta.get('namespace', 'default')}/{meta.get('name', 'unknown')}"
        pod_flags = []
        if spec.get("hostPID"):
            pod_flags.append("hostPID")
        if spec.get("hostNetwork"):
            pod_flags.append("hostNetwork")
        containers = (spec.get("initContainers") or []) + (spec.get("containers") or [])
        for ctr in containers:
            sc = ctr.get("securityContext") or {}
            cflags = list(pod_flags)
            if sc.get("privileged") is True:
                cflags.append("privileged")
            if sc.get("readOnlyRootFilesystem") is not True:
                cflags.append("writableRootfs")
            if cflags:
                findings.append({
                    "pod": pod_ref,
                    "container": ctr.get("name"),
                    "flags": cflags,
                })
    return findings

if __name__ == "__main__":
    print(json.dumps(audit_podlist(sys.argv[1]), indent=2))
