use std::env;
use std::fs;

fn read_u16_le(buf: &[u8], off: usize) -> Option<u16> {
    Some(u16::from_le_bytes(buf.get(off..off + 2)?.try_into().ok()?))
}

fn read_u32_le(buf: &[u8], off: usize) -> Option<u32> {
    Some(u32::from_le_bytes(buf.get(off..off + 4)?.try_into().ok()?))
}

fn read_u64_le(buf: &[u8], off: usize) -> Option<u64> {
    Some(u64::from_le_bytes(buf.get(off..off + 8)?.try_into().ok()?))
}

pub fn audit_elf64_wx(buf: &[u8]) -> Result<Vec<(usize, u64, u64)>, &'static str> {
    if buf.len() < 64 || &buf[0..4] != &[0x7f, b'E', b'L', b'F'] {
        return Err("invalid ELF magic or header size");
    }
    if buf[4] != 2 || buf[5] != 1 {
        return Err("unsupported ELF class or endianness");
    }
    let phoff = read_u64_le(buf, 32).ok_or("bad phoff")? as usize;
    let phentsize = read_u16_le(buf, 54).ok_or("bad phentsize")? as usize;
    let phnum = read_u16_le(buf, 56).ok_or("bad phnum")? as usize;
    if phentsize < 56 {
        return Err("phentsize too small for ELF64");
    }
    let table_end = phoff.checked_add(phentsize.checked_mul(phnum).ok_or("overflow")?).ok_or("overflow")?;
    if table_end > buf.len() {
        return Err("program header table out of bounds");
    }
    let mut wx_segments = Vec::new();
    for i in 0..phnum {
        let base = phoff + i * phentsize;
        let p_type = read_u32_le(buf, base).ok_or("bad p_type")?;
        let p_flags = read_u32_le(buf, base + 4).ok_or("bad p_flags")?;
        let p_vaddr = read_u64_le(buf, base + 16).ok_or("bad p_vaddr")?;
        let p_memsz = read_u64_le(buf, base + 40).ok_or("bad p_memsz")?;
        if p_type == 1 && (p_flags & 0x3) == 0x3 {
            wx_segments.push((i, p_vaddr, p_memsz));
        }
    }
    Ok(wx_segments)
}

fn main() {
    let path = env::args().nth(1).expect("usage: elf_audit <file>");
    let data = fs::read(path).expect("failed to read binary");
    match audit_elf64_wx(&data) {
        Ok(hits) => {
            for (idx, vaddr, memsz) in hits {
                println!("wx_pt_load index={} vaddr=0x{:x} memsz={}", idx, vaddr, memsz);
            }
        }
        Err(e) => eprintln!("audit_error: {}", e),
    }
}
