import argparse
import gzip
import heapq
import json
import sys

def open_maybe_gz(path: str):
    if path.endswith(".gz"):
        return gzip.open(path, "rt", encoding="utf-8")
    return open(path, "r", encoding="utf-8")

def stream_collector(path: str, offsets: dict[str, int]):
    with open_maybe_gz(path) as fh:
        for seq, line in enumerate(fh):
            if not line.strip():
                continue
            ev = json.loads(line)
            col = ev.get("collector", "")
            adj_ms = int(ev["epoch_ms"]) + offsets.get(col, 0)
            ev["adj_epoch_ms"] = adj_ms
            yield (adj_ms, path, seq, ev)

def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--skew", action="append", default=[], help="collector=offset_ms")
    ap.add_argument("--start-ms", type=int, default=0)
    ap.add_argument("--end-ms", type=int, default=10**15)
    ap.add_argument("files", nargs="+")
    args = ap.parse_args()
    offsets = {}
    for item in args.skew:
        k, v = item.split("=", 1)
        offsets[k] = int(v)
    gens = [stream_collector(f, offsets) for f in args.files]
    for adj_ms, _, _, ev in heapq.merge(*gens, key=lambda x: (x[0], x[1], x[2])):
        if adj_ms < args.start_ms:
            continue
        if adj_ms > args.end_ms:
            break
        sys.stdout.write(json.dumps(ev) + "\n")

if __name__ == "__main__":
    main()
