import heapq
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

def extract_utc_us(rec: dict) -> int:
    if "unix_us" in rec:
        return int(rec["unix_us"])
    if "epoch_ms" in rec:
        return int(rec["epoch_ms"]) * 1000
    dt = datetime.fromisoformat(rec["iso_ts"].replace("Z", "+00:00")).astimezone(timezone.utc)
    return int(dt.timestamp() * 1_000_000)

def read_normalized(path: str, skew_us: dict[str, int]):
    with open(path, "r", encoding="utf-8") as fh:
        for idx, line in enumerate(fh):
            if not line.strip():
                continue
            rec = json.loads(line)
            adj_us = extract_utc_us(rec) + skew_us.get(rec.get("src", ""), 0)
            dt_str = datetime.fromtimestamp(adj_us / 1_000_000, tz=timezone.utc).isoformat()
            out = {"utc_us": adj_us, "utc_iso": dt_str, "src": rec.get("src", ""), "raw": rec}
            yield (adj_us, path, idx, out)

def main() -> None:
    skew_us = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
    iters = [read_normalized(p, skew_us) for p in sys.argv[2:]]
    for _, _, _, item in heapq.merge(*iters, key=lambda t: (t[0], t[1], t[2])):
        sys.stdout.write(json.dumps(item) + "\n")

if __name__ == "__main__":
    main()
