import json
import math
import sys
from collections import Counter, defaultdict

MULTI_TLDS = {"co.uk", "org.uk", "com.au", "co.jp"}
HEX_CHARS = set("0123456789abcdef")

def split_etld1(fqdn: str) -> tuple[str, str]:
    parts = [p for p in fqdn.rstrip(".").lower().split(".") if p]
    if len(parts) < 3:
        return "", ".".join(parts)
    tail2 = ".".join(parts[-2:])
    if tail2 in MULTI_TLDS:
        if len(parts) < 4:
            return "", ".".join(parts)
        return "".join(parts[:-3]), ".".join(parts[-3:])
    return "".join(parts[:-2]), tail2

def shannon(s: str) -> float:
    n = len(s)
    return -sum((c / n) * math.log2(c / n) for c in Counter(s).values()) if n else 0.0

def triage_dns_zones(path: str) -> list[dict]:
    subs = defaultdict(set)
    metrics = defaultdict(list)
    with open(path, "r", encoding="utf-8") as fh:
        for line in fh:
            if not line.strip():
                continue
            sub, zone = split_etld1(json.loads(line).get("fqdn", ""))
            if not sub:
                continue
            subs[zone].add(sub)
            hex_ratio = sum(1 for ch in sub if ch in HEX_CHARS) / len(sub)
            metrics[zone].append((shannon(sub), hex_ratio))
    results = []
    for zone, seen in subs.items():
        pts = metrics[zone]
        avg_ent = sum(x[0] for x in pts) / len(pts)
        avg_hex = sum(x[1] for x in pts) / len(pts)
        if len(seen) >= 20 and avg_ent > 3.6 and avg_hex > 0.75:
            results.append({
                "etld1": zone,
                "distinct_prefixes": len(seen),
                "avg_entropy": round(avg_ent, 3),
                "avg_hex_ratio": round(avg_hex, 3),
            })
    return sorted(results, key=lambda r: r["avg_entropy"], reverse=True)

if __name__ == "__main__":
    print(json.dumps(triage_dns_zones(sys.argv[1]), indent=2))
```

