package main

import (
	"encoding/json"
	"fmt"
	"os"
)

type OCISpec struct {
	Process struct {
		NoNewPrivileges bool `json:"noNewPrivileges"`
	} `json:"process"`
	Root struct {
		Readonly bool `json:"readonly"`
	} `json:"root"`
	Linux struct {
		Namespaces []struct {
			Type string `json:"type"`
		} `json:"namespaces"`
	} `json:"linux"`
}

func auditBundle(path string) []string {
	raw, err := os.ReadFile(path)
	if err != nil {
		return []string{"read_error"}
	}
	var spec OCISpec
	if err := json.Unmarshal(raw, &spec); err != nil {
		return []string{"invalid_json"}
	}
	nsSet := map[string]bool{}
	for _, ns := range spec.Linux.Namespaces {
		nsSet[ns.Type] = true
	}
	var flags []string
	if !nsSet["pid"] {
		flags = append(flags, "host_pid_shared")
	}
	if !nsSet["network"] {
		flags = append(flags, "host_network_shared")
	}
	if !spec.Root.Readonly {
		flags = append(flags, "writable_rootfs")
	}
	if !spec.Process.NoNewPrivileges {
		flags = append(flags, "no_new_privileges_disabled")
	}
	return flags
}

func main() {
	for _, p := range os.Args[1:] {
		if issues := auditBundle(p); len(issues) > 0 {
			out, _ := json.Marshal(map[string]any{"bundle": p, "issues": issues})
			fmt.Println(string(out))
		}
	}
}
