import json
import math
import struct
import sys
from collections import Counter
from pathlib import Path

MZ_SIG = bytes.fromhex("4d5a")
PE_SIG = bytes.fromhex("50450000")
IMAGE_SCN_MEM_EXECUTE = 0x20000000
IMAGE_SCN_MEM_WRITE = 0x80000000

def entropy(data: bytes) -> float:
    if not data:
        return 0.0
    n = len(data)
    return -sum((c / n) * math.log2(c / n) for c in Counter(data).values())

def audit_pe_sections(path: str) -> dict:
    buf = Path(path).read_bytes()
    if len(buf) < 64 or buf[:2] != MZ_SIG:
        return {"valid": False, "error": "not_mz"}
    pe_off, = struct.unpack("<I", buf[60:64])
    if pe_off + 24 > len(buf) or buf[pe_off:pe_off + 4] != PE_SIG:
        return {"valid": False, "error": "bad_pe_header"}
    _, num_sec, _, _, _, opt_size, _ = struct.unpack("<HHIIIHH", buf[pe_off + 4:pe_off + 24])
    sec_base = pe_off + 24 + opt_size
    sections = []
    flagged = []
    for i in range(num_sec):
        off = sec_base + i * 40
        if off + 40 > len(buf):
            break
        raw_name, vsize, vaddr, raw_size, raw_ptr = struct.unpack("<8sIIII", buf[off:off + 24])
        chars, = struct.unpack("<I", buf[off + 36:off + 40])
        name = raw_name.rstrip(b"\x00").decode("latin1")
        chunk = buf[raw_ptr:min(len(buf), raw_ptr + raw_size)] if raw_size else b""
        ent = round(entropy(chunk), 3)
        wx = bool((chars & IMAGE_SCN_MEM_EXECUTE) and (chars & IMAGE_SCN_MEM_WRITE))
        info = {"name": name, "vaddr": hex(vaddr), "raw_size": raw_size, "entropy": ent, "wx": wx}
        sections.append(info)
        if ent > 7.2 or wx:
            flagged.append(info)
    return {"valid": True, "sections": sections, "flagged": flagged}

if __name__ == "__main__":
    print(json.dumps(audit_pe_sections(sys.argv[1]), indent=2))
