import ipaddress
import json
import sys
from collections import defaultdict, deque

def subnet24(ip_str: str) -> str:
    return str(ipaddress.ip_interface(f"{ip_str}/24").network)

def detect_subnet_stuffing(path: str, window_s: int = 120, min_users: int = 30) -> list[dict]:
    buckets = defaultdict(deque)
    alerts = []
    with open(path, "r", encoding="utf-8") as fh:
        for line in fh:
            if not line.strip():
                continue
            ev = json.loads(line)
            ts = float(ev["ts"])
            cidr = subnet24(ev["ip"])
            q = buckets[cidr]
            while q and ts - q[0][0] > window_s:
                q.popleft()
            q.append((ts, ev["ip"], ev["username"], ev["outcome"]))
            if ev["outcome"] == "SUCCESS":
                users = {u for _, _, u, _ in q}
                succ = [u for _, _, u, out in q if out == "SUCCESS"]
                rate = len(succ) / len(q)
                if len(users) >= min_users and rate < 0.05:
                    alerts.append({
                        "subnet": cidr,
                        "ts": ts,
                        "distinct_users": len(users),
                        "distinct_ips": len({i for _, i, _, _ in q}),
                        "succeeded_users": sorted(set(succ)),
                        "success_rate": round(rate, 4),
                    })
                    q.clear()
    return alerts

if __name__ == "__main__":
    print(json.dumps(detect_subnet_stuffing(sys.argv[1]), indent=2))
