use std::env;
use std::fs;

fn u32_le(b: &[u8], o: usize) -> Option<u32> {
    Some(u32::from_le_bytes(b.get(o..o + 4)?.try_into().ok()?))
}

fn u64_le(b: &[u8], o: usize) -> Option<u64> {
    Some(u64::from_le_bytes(b.get(o..o + 8)?.try_into().ok()?))
}

pub fn check_macho64(buf: &[u8]) -> Result<Vec<(String, u32, u32)>, &'static str> {
    if buf.len() < 32 || u32_le(buf, 0) != Some(0xFEED_FACF) {
        return Err("not a 64-bit little-endian Mach-O");
    }
    let ncmds = u32_le(buf, 16).ok_or("bad ncmds")? as usize;
    let sizeofcmds = u32_le(buf, 20).ok_or("bad sizeofcmds")? as usize;
    let end_cmds = 32usize.checked_add(sizeofcmds).ok_or("cmd overflow")?;
    if end_cmds > buf.len() {
        return Err("sizeofcmds exceeds file size");
    }
    let mut pos = 32usize;
    let mut hits = Vec::new();
    for _ in 0..ncmds {
        let cmd = u32_le(buf, pos).ok_or("truncated cmd")?;
        let cmdsize = u32_le(buf, pos + 4).ok_or("truncated cmdsize")? as usize;
        if cmdsize < 8 || pos.checked_add(cmdsize).map_or(true, |e| e > end_cmds) {
            return Err("invalid cmdsize");
        }
        if cmd == 0x19 {
            if cmdsize < 72 {
                return Err("short LC_SEGMENT_64");
            }
            let raw_name = &buf[pos + 8..pos + 24];
            let nul = raw_name.iter().position(|&c| c == 0).unwrap_or(16);
            let segname = String::from_utf8_lossy(&raw_name[..nul]).into_owned();
            let fileoff = u64_le(buf, pos + 40).ok_or("bad fileoff")?;
            let filesize = u64_le(buf, pos + 48).ok_or("bad filesize")?;
            if fileoff.checked_add(filesize).map_or(true, |e| e > buf.len() as u64) {
                return Err("segment file range out of bounds");
            }
            let maxprot = u32_le(buf, pos + 56).ok_or("bad maxprot")?;
            let initprot = u32_le(buf, pos + 60).ok_or("bad initprot")?;
            if (initprot & 0x6) == 0x6 || (maxprot & 0x6) == 0x6 {
                hits.push((segname, initprot, maxprot));
            }
        }
        pos += cmdsize;
    }
    Ok(hits)
}

fn main() {
    let path = env::args().nth(1).expect("usage: macho_audit <binary>");
    let buf = fs::read(path).expect("read failed");
    match check_macho64(&buf) {
        Ok(list) => {
            for (seg, initp, maxp) in list {
                println!("wx_segment name={} initprot=0x{:x} maxprot=0x{:x}", seg, initp, maxp);
            }
        }
        Err(e) => eprintln!("error: {}", e),
    }
}
