```python
import json
import struct
import sys
from pathlib import Path

FAT_MAGIC = 0xCAFEBABE
FAT_MAGIC_64 = 0xCAFEBABF
THIN_MAGICS = {0xFEEDFACE, 0xCEFAEDFE, 0xFEEDFACF, 0xCFFAEDFE}
CPU_NAMES = {
    0x00000007: "i386",
    0x01000007: "x86_64",
    0x0000000C: "arm",
    0x0100000C: "arm64",
}

def parse_macho_universal(path: str) -> dict:
    buf = Path(path).read_bytes()
    if len(buf) < 8:
        return {"valid": False, "issues": ["truncated_fat_header"], "slices": []}
    magic, nfat = struct.unpack(">II", buf[:8])
    if magic not in (FAT_MAGIC, FAT_MAGIC_64):
        return {"valid": False, "issues": [f"unexpected_magic:{hex(magic)}"], "slices": []}
    if nfat == 0 or nfat > 32:
        return {"valid": False, "issues": [f"unreasonable_nfat:{nfat}"], "slices": []}

    is_64 = magic == FAT_MAGIC_64
    ent_fmt = ">iiQQII" if is_64 else ">iiIII"
    ent_sz = struct.calcsize(ent_fmt)
    hdr_end = 8 + nfat * ent_sz
    if hdr_end > len(buf):
        return {"valid": False, "issues": ["truncated_arch_table"], "slices": []}

    issues = []
    slices = []
    ranges = []
    for idx in range(nfat):
        off_ent = 8 + idx * ent_sz
        fields = struct.unpack(ent_fmt, buf[off_ent:off_ent + ent_sz])
        cputype, cpusubtype, s_off, s_size, align = fields[:5]
        end_off = s_off + s_size
        inner_ok = False
        if s_off < hdr_end or end_off > len(buf):
            issues.append(f"slice_{idx}_out_of_bounds")
        elif s_size >= 4:
            inner_magic, = struct.unpack(">I", buf[s_off:s_off + 4])
            inner_ok = inner_magic in THIN_MAGICS
            if not inner_ok:
                issues.append(f"slice_{idx}_bad_inner_magic:{hex(inner_magic)}")
        ranges.append((s_off, end_off, idx))
        slices.append({
            "index": idx,
            "arch": CPU_NAMES.get(cputype & 0xFFFFFFFF, hex(cputype & 0xFFFFFFFF)),
            "cpusubtype": cpusubtype & 0xFFFFFFFF,
            "offset": s_off,
            "size": s_size,
            "align_pow2": align,
            "inner_macho_valid": inner_ok,
        })

    ranges.sort()
    for i in range(1, len(ranges)):
        if ranges[i][0] < ranges[i - 1][1]:
            issues.append(f"overlapping_slices:{ranges[i - 1][2]}_and_{ranges[i][2]}")
    return {"valid": not issues, "is_fat64": is_64, "issues": issues, "slices": slices}

if __name__ == "__main__":
    print(json.dumps(parse_macho_universal(sys.argv[1]), indent=2))
```

