from datetime import datetime, timezone
from pathlib import Path

def parse_utc(ts_str: str) -> float:
    return datetime.fromisoformat(ts_str.replace("Z", "+00:00")).astimezone(timezone.utc).timestamp()

def correlate_persistence_drift(baseline_path: str, snapshots_jsonl: str) -> list[dict]:
    raw_base = json.loads(Path(baseline_path).read_text(encoding="utf-8"))
    allowed_crons = {
        role: {(c["user"], c["spec"]) for c in cfg.get("crons", [])}
        for role, cfg in raw_base.items()
    }
    allowed_timers = {
        role: {(t["unit"], t["exec_sha256"]) for t in cfg.get("timers", [])}
        for role, cfg in raw_base.items()
    }

    rows = []
    with open(snapshots_jsonl, "r", encoding="utf-8") as fh:
        for line in fh:
            if line.strip():
                rows.append(json.loads(line))
    rows.sort(key=lambda r: parse_utc(r["captured_utc"]))

    seen_drift: set[tuple] = set()
    timeline = []
    for snap in rows:
        host = snap["host"]
        role = snap.get("role", "default")
        ts = snap["captured_utc"]
        base_c = allowed_crons.get(role, set())
        base_t = allowed_timers.get(role, set())

        for c in snap.get("crons", []):
            pair = (c["user"], c["spec"])
            sig = (host, "cron", pair)
            if pair not in base_c and sig not in seen_drift:
                seen_drift.add(sig)
                timeline.append({"captured_utc": ts, "host": host, "kind": "unauthorized_cron", "detail": c})

        for t in snap.get("timers", []):
            pair = (t["unit"], t["exec_sha256"])
            sig = (host, "timer", pair)
            if pair not in base_t and sig not in seen_drift:
                seen_drift.add(sig)
                timeline.append({"captured_utc": ts, "host": host, "kind": "timer_drift", "detail": t})
