	QType string `json:"qtype_name"`
}

type PairStats struct {
	Seen   map[string]struct{}
	Count  int
	EntSum float64
	B32Sum float64
}

func scoreLabel(raw string) (float64, float64) {
	freq := map[rune]int{}
	b32 := 0
	runes := []rune(raw)
	for _, r := range runes {
		freq[r]++
		if (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z') || (r >= '2' && r <= '7') {
			b32++
		}
	}
	n := float64(len(runes))
	ent := 0.0
	for _, c := range freq {
		p := float64(c) / n
		ent -= p * math.Log2(p)
	}
	return ent, float64(b32) / n
}

func main() {
	f, err := os.Open(os.Args[1])
	if err != nil {
		panic(err)
	}
	defer f.Close()

	agg := map[string]*PairStats{}
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		var r DnsRec
		if err := json.Unmarshal(sc.Bytes(), &r); err != nil {
			continue
		}
		parts := strings.Split(strings.TrimSuffix(r.Query, "."), ".")
		if len(parts) < 3 || len(parts[0]) < 16 {
			continue
		}
		base := strings.ToLower(parts[len(parts)-2] + "." + parts[len(parts)-1])
		key := r.OrigH + "|" + base
		st, ok := agg[key]
		if !ok {
			st = &PairStats{Seen: map[string]struct{}{}}
			agg[key] = st
		}
		lbl := strings.ToUpper(parts[0])
		st.Seen[lbl] = struct{}{}
		ent, b32 := scoreLabel(lbl)
		st.Count++
		st.EntSum += ent
		st.B32Sum += b32
	}
	for key, st := range agg {
		meanEnt := st.EntSum / float64(st.Count)
		meanB32 := st.B32Sum / float64(st.Count)
		if len(st.Seen) >= 30 && meanEnt > 3.85 && meanB32 > 0.85 {
			kv := strings.SplitN(key, "|", 2)
			out, _ := json.Marshal(map[string]any{
				"orig_h": kv[0], "base_domain": kv[1],
				"unique_labels": len(st.Seen), "mean_entropy": meanEnt, "b32_ratio": meanB32,
			})
			fmt.Println(string(out))
		}
	}
}
