    let start = line.find(pat)? + pat.len();
    let digits: String = line[start..].chars().skip_while(|c| c.is_whitespace()).take_while(|c| c.is_ascii_digit()).collect();
    digits.parse().ok()
}

fn main() {
    let path = env::args().nth(1).expect("usage: ssh_fanout <sshd.jsonl>");
    let file = File::open(path).expect("open failed");
    let mut windows: HashMap<String, VecDeque<(i64, String, String)>> = HashMap::new();
