import ipaddress
import json
import sys
from collections import defaultdict

def to_slash24(ip_str: str) -> str | None:
    try:
        addr = ipaddress.ip_address(ip_str)
        if addr.version == 4:
            return str(ipaddress.ip_interface(f"{ip_str}/24").network)
    except ValueError:
        return None
    return None

def detect_fast_flux(path: str, min_subnets: int = 8, max_mean_ttl: float = 60.0) -> list[dict]:
    ips_seen: dict[tuple[int, str], set[str]] = defaultdict(set)
    subnets_seen: dict[tuple[int, str], set[str]] = defaultdict(set)
    ttls: dict[tuple[int, str], list[int]] = defaultdict(list)

    with open(path, "r", encoding="utf-8") as fh:
        for line in fh:
            if not line.strip():
                continue
            ev = json.loads(line)
            if ev.get("qtype") != "A":
                continue
            bucket = int(ev["ts_s"]) // 600 * 600
            qname = ev.get("qname", "").rstrip(".").lower()
            key = (bucket, qname)
            ttls[key].append(int(ev.get("ttl", 0)))
            for ip in ev.get("answer_ips") or []:
                s24 = to_slash24(ip)
                if s24:
                    ips_seen[key].add(ip)
                    subnets_seen[key].add(s24)

    alerts = []
    for (bucket, qname), s24s in subnets_seen.items():
        mean_ttl = sum(ttls[(bucket, qname)]) / len(ttls[(bucket, qname)])
        if len(s24s) >= min_subnets and mean_ttl <= max_mean_ttl:
            alerts.append({
                "window_epoch_s": bucket,
                "qname": qname,
                "distinct_ips": len(ips_seen[(bucket, qname)]),
                "distinct_slash24s": len(s24s),
                "mean_ttl_s": round(mean_ttl, 2),
            })
    return sorted(alerts, key=lambda r: (-r["distinct_slash24s"], r["window_epoch_s"]))

if __name__ == "__main__":
    print(json.dumps(detect_fast_flux(sys.argv[1]), indent=2))
