import bisect
import json
import sys
from collections import defaultdict

def build_vpn_index(vpn_jsonl: str) -> dict[tuple[str, str], tuple[list[int], list[int]]]:
    raw: dict[tuple[str, str], list[tuple[int, int]]] = defaultdict(list)
    with open(vpn_jsonl, "r", encoding="utf-8") as fh:
        for line in fh:
            if not line.strip():
                continue
            r = json.loads(line)
            key = (r["assigned_nat_ip"], r["employee_email"].lower())
            raw[key].append((int(r["login_ts"]), int(r["logout_ts"])))

    merged_idx = {}
    for key, ivals in raw.items():
        ivals.sort()
        coalesced = [ivals[0]]
        for s, e in ivals[1:]:
            ps, pe = coalesced[-1]
            if s <= pe:
                coalesced[-1] = (ps, max(pe, e))
            else:
                coalesced.append((s, e))
        merged_idx[key] = ([x[0] for x in coalesced], [x[1] for x in coalesced])
    return merged_idx

def has_active_lease(idx: dict, ip: str, email: str, ts: int) -> bool:
    entry = idx.get((ip, email.lower()))
    if not entry:
        return False
    starts, ends = entry
    pos = bisect.bisect_right(starts, ts) - 1
    return pos >= 0 and ts <= ends[pos]

def find_unleased_cloud_calls(vpn_path: str, cloud_path: str) -> list[dict]:
    idx = build_vpn_index(vpn_path)
    anomalies = []
    with open(cloud_path, "r", encoding="utf-8") as fh:
        for line in fh:
            if not line.strip():
                continue
            ev = json.loads(line)
            if not has_active_lease(idx, ev["request_ip"], ev["principal_email"], int(ev["event_ts"])):
                anomalies.append(ev)
    return sorted(anomalies, key=lambda x: x["event_ts"])

if __name__ == "__main__":
