use std::collections::{HashMap, HashSet};
use std::env;
use std::fs::File;
use std::io::{BufRead, BufReader};

fn get_json_str<'a>(s: &'a str, key: &str) -> Option<&'a str> {
    let pat = format!("\"{}\":\"", key);
    let lo = s.find(&pat)? + pat.len();
    let hi = s[lo..].find('"')? + lo;
    Some(&s[lo..hi])
}

fn is_dga_sld(sld: &str) -> bool {
    if sld.len() < 10 { return false; }
    let mut counts = [0usize; 256];
    let (mut cur_cons, mut max_cons) = (0usize, 0usize);
    for b in sld.bytes() {
        let c = b.to_ascii_lowercase();
        counts[c as usize] += 1;
        let is_alpha = c.is_ascii_lowercase();
        let is_vowel = matches!(c, b'a' | b'e' | b'i' | b'o' | b'u' | b'y');
        if is_alpha && !is_vowel {
            cur_cons += 1;
            max_cons = max_cons.max(cur_cons);
        } else {
            cur_cons = 0;
        }
    }
    if max_cons < 5 { return false; }
    let n = sld.len() as f64;
    let ent: f64 = counts.iter().filter(|&&c| c > 0).map(|&c| {
        let p = c as f64 / n;
        -p * p.log2()
    }).sum();
    ent >= 3.3
}

fn main() {
    let path = env::args().nth(1).expect("usage: dga_hunt <pdns.jsonl>");
    let f = File::open(path).expect("open failed");
    let mut hits: HashMap<String, HashSet<String>> = HashMap::new();

    for line in BufReader::new(f).lines().map_while(Result::ok) {
        if get_json_str(&line, "rcode") != Some("NXDOMAIN") { continue; }
        let (Some(ip), Some(qn)) = (get_json_str(&line, "src_ip"), get_json_str(&line, "qname")) else { continue };
        let parts: Vec<&str> = qn.trim_end_matches('.').split('.').collect();
        if parts.len() < 2 { continue; }
        let sld = parts[parts.len() - 2].to_ascii_lowercase();
        if is_dga_sld(&sld) {
            hits.entry(ip.to_string()).or_default().insert(sld);
        }
    }
    for (ip, doms) in hits {
        if doms.len() >= 40 {
            println!("{{\"src_ip\":\"{}\",\"dga_nxdomain_count\":{}}}", ip, doms.len());
        }
    }
}
