```python
import json
import struct
import sys
from datetime import datetime, timezone
from pathlib import Path

GZ_MAGIC = bytes.fromhex("1f8b")
FHCRC, FEXTRA, FNAME, FCOMMENT = 0x02, 0x04, 0x08, 0x10

def parse_gzip_header(path: str, ref_now_s: int = 1795392000) -> dict:
    buf = Path(path).read_bytes()
    if len(buf) < 10 or buf[:2] != GZ_MAGIC:
        return {"valid": False, "issues": ["bad_gzip_magic"]}

    cm, flg, mtime, xfl, os_code = struct.unpack("<BBIBB", buf[2:10])
    pos = 10
    issues = []
    if cm != 8:
        issues.append(f"unsupported_compression_method:{cm}")

    if flg & FEXTRA:
        if pos + 2 > len(buf):
            return {"valid": False, "issues": ["truncated_fextra"]}
        xlen, = struct.unpack("<H", buf[pos:pos + 2])
        pos += 2 + xlen

    orig_name = None
    if flg & FNAME:
        nul = buf.find(0, pos)
        if nul < 0:
            return {"valid": False, "issues": ["unterminated_fname"]}
        orig_name = buf[pos:nul].decode("latin1")
        pos = nul + 1
        if orig_name.startswith("/") or ".." in orig_name.split("/"):
            issues.append(f"unsafe_fname_traversal:{orig_name}")

    comment = None
    if flg & FCOMMENT:
        nul = buf.find(0, pos)
        if nul < 0:
            return {"valid": False, "issues": ["unterminated_fcomment"]}
        comment = buf[pos:nul].decode("latin1")
        pos = nul + 1

    if flg & FHCRC:
        pos += 2
    if pos > len(buf):
        issues.append("header_exceeds_file_len")
    if mtime > ref_now_s:
        issues.append(f"future_mtime:{mtime}")

    mtime_iso = datetime.fromtimestamp(mtime, tz=timezone.utc).isoformat() if mtime else None
    return {
        "valid": not issues,
        "issues": issues,
        "mtime_epoch": mtime,
        "mtime_utc": mtime_iso,
        "extra_flags": xfl,
        "os_code": os_code,
        "fname": orig_name,
        "fcomment": comment,
        "deflate_offset": pos,
    }

if __name__ == "__main__":
    print(json.dumps(parse_gzip_header(sys.argv[1]), indent=2))
