import json
import sys

TYPE_ORDER = {"EXEC": 0, "CONNECT": 1, "EXIT": 2}

def correlate_ebpf_connects(jsonl_path: str) -> list[dict]:
    events = []
    with open(jsonl_path, "r", encoding="utf-8") as fh:
        for line in fh:
            if line.strip():
                events.append(json.loads(line))
    events.sort(key=lambda e: (int(e["boot_ns"]), TYPE_ORDER.get(e["type"], 9)))

    active_pid: dict[int, tuple[int, int]] = {}
    proc_table: dict[tuple[int, int], dict] = {}
    enriched = []

    for ev in events:
        ns = int(ev["boot_ns"])
        pid = int(ev["pid"])
        etype = ev["type"]

        if etype == "EXEC":
            ppid = int(ev.get("ppid", 0))
            parent_key = active_pid.get(ppid)
            pkey = (pid, ns)
            proc_table[pkey] = {"pid": pid, "exe": ev.get("exe", "?"), "parent": parent_key}
            active_pid[pid] = pkey
        elif etype == "CONNECT":
            cur = active_pid.get(pid)
            chain = []
            depth = 0
            while cur and cur in proc_table and depth < 16:
                node = proc_table[cur]
                chain.append(f"{node['exe']}[{node['pid']}]")
                cur = node["parent"]
                depth += 1
            enriched.append({
                "boot_ns": ns,
                "pid": pid,
                "dst": ev.get("dst"),
                "ancestry": list(reversed(chain)),
            })
        elif etype == "EXIT":
            active_pid.pop(pid, None)
    return enriched

if __name__ == "__main__":
