package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

type AuthQuery struct {
	QName string `json:"qname"`
	QType string `json:"qtype"`
}

type ZoneAgg struct {
	TotalQ     int
	TunnelType int
	SubChars   int
	B64Chars   int
}

func isB64URL(b byte) bool {
	return (b >= 'A' && b <= 'Z') || (b >= 'a' && b <= 'z') || (b >= '0' && b <= '9') || b == '-' || b == '_'
}

func main() {
	f, err := os.Open(os.Args[1])
	if err != nil {
		panic(err)
	}
	defer f.Close()

	zones := map[string]*ZoneAgg{}
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		var q AuthQuery
		if json.Unmarshal(sc.Bytes(), &q) != nil {
			continue
		}
		parts := strings.Split(strings.TrimSuffix(q.QName, "."), ".")
		if len(parts) < 3 {
			continue
		}
		base := strings.ToLower(parts[len(parts)-2] + "." + parts[len(parts)-1])
		sub := strings.Join(parts[:len(parts)-2], "")
		z, ok := zones[base]
		if !ok {
			z = &ZoneAgg{}
			zones[base] = z
		}
		z.TotalQ++
		if q.QType == "TXT" || q.QType == "NULL" || q.QType == "CNAME" {
			z.TunnelType++
		}
		z.SubChars += len(sub)
		for i := 0; i < len(sub); i++ {
			if isB64URL(sub[i]) {
				z.B64Chars++
			}
		}
	}
	for dom, z := range zones {
		if z.TotalQ < 50 || z.SubChars < 2048 {
			continue
		}
		tShare := float64(z.TunnelType) / float64(z.TotalQ)
		b64Ratio := float64(z.B64Chars) / float64(z.SubChars)
		if tShare > 0.80 && b64Ratio > 0.95 {
			b, _ := json.Marshal(map[string]any{
				"base_domain": dom, "queries": z.TotalQ,
				"tunnel_qtype_ratio": tShare, "sub_chars": z.SubChars, "b64url_ratio": b64Ratio,
			})
			fmt.Println(string(b))
		}
	}
}
