use std::env;
use std::fs::File;
use std::io::{BufRead, BufReader};

const CAP_SYS_MODULE: u64 = 1 << 16;
const CAP_SYS_ADMIN: u64 = 1 << 21;

fn field_str<'a>(s: &'a str, k: &str) -> Option<&'a str> {
    let p = format!("\"{}\":\"", k);
    let a = s.find(&p)? + p.len();
    let b = s[a..].find('"')? + a;
    Some(&s[a..b])
}

fn field_u64(s: &str, k: &str) -> Option<u64> {
    let p = format!("\"{}\":", k);
    let a = s.find(&p)? + p.len();
    let num: String = s[a..].chars().skip_while(|c| c.is_whitespace()).take_while(|c| c.is_ascii_digit()).collect();
    num.parse().ok()
}

fn main() {
    let path = env::args().nth(1).expect("usage: proc_audit <procs.jsonl>");
    let fh = File::open(path).expect("open failed");

    for line in BufReader::new(fh).lines().map_while(Result::ok) {
        let Some(cid) = field_str(&line, "container_id") else { continue };
        if cid.is_empty() { continue; }
        let (Some(pid), Some(sec), Some(mnt), Some(hmnt), Some(cap_hex)) = (
            field_u64(&line, "pid"),
            field_u64(&line, "seccomp_mode"),
            field_u64(&line, "mnt_ns"),
            field_u64(&line, "host_mnt_ns"),
            field_str(&line, "cap_eff_hex"),
        ) else { continue };

        let caps = u64::from_str_radix(cap_hex, 16).unwrap_or(0);
        let mut flags = Vec::new();
        if mnt == hmnt { flags.push("host_mount_ns"); }
        if sec == 0 { flags.push("seccomp_disabled"); }
        if (caps & CAP_SYS_ADMIN) != 0 { flags.push("cap_sys_admin"); }
        if (caps & CAP_SYS_MODULE) != 0 { flags.push("cap_sys_module"); }

        if !flags.is_empty() {
            println!(
                "{{\"pid\":{},\"container_id\":\"{}\",\"flags\":\"{}\"}}",
                pid, cid, flags.join(",")
            );
        }
    }
}
