package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
)

func readULEB(b []byte, pos *int) (uint32, error) {
	var res uint32
	for shift := uint(0); shift < 35; shift += 7 {
		if *pos >= len(b) {
			return 0, errors.New("truncated uleb128")
		}
		byteVal := b[*pos]
		*pos++
		res |= uint32(byteVal&0x7f) << shift
		if (byteVal & 0x80) == 0 {
			return res, nil
		}
	}
	return 0, errors.New("uleb128 overflow")
}

func readStr(b []byte, pos *int) (string, error) {
	n, err := readULEB(b, pos)
	if err != nil || *pos+int(n) > len(b) {
		return "", errors.New("bad string bounds")
	}
	s := string(b[*pos : *pos+int(n)])
	*pos += int(n)
	return s, nil
}

func parseWasmImports(buf []byte) ([]string, error) {
	wasmHdr := []byte{0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00}
	if len(buf) < 8 || !bytes.Equal(buf[:8], wasmHdr) {
		return nil, errors.New("invalid wasm header")
	}
	pos := 8
	var imports []string
	for pos < len(buf) {
		secID := buf[pos]
		pos++
		secLen, err := readULEB(buf, &pos)
		if err != nil || pos+int(secLen) > len(buf) {
			return nil, errors.New("section out of bounds")
		}
		if secID == 2 {
			p := pos
			cnt, err := readULEB(buf, &p)
			if err != nil {
				return nil, err
			}
			for i := uint32(0); i < cnt; i++ {
				mod, err1 := readStr(buf, &p)
				fld, err2 := readStr(buf, &p)
				if err1 != nil || err2 != nil || p >= pos+int(secLen) {
					return imports, nil
				}
				kind := buf[p]
				p++
				if kind == 0 {
					_, _ = readULEB(buf, &p)
				}
				imports = append(imports, mod+"."+fld)
			}
		}
		pos += int(secLen)
	}
	return imports, nil
}

func main() {
	raw, _ := os.ReadFile(os.Args[1])
	imps, err := parseWasmImports(raw)
	out, _ := json.Marshal(map[string]any{"valid": err == nil, "imports": imps})
	fmt.Println(string(out))
}
