```python
import json
import math
import sys
from collections import Counter, defaultdict

def shannon_entropy(s: str) -> float:
    if not s:
        return 0.0
    n = len(s)
    return -sum((c / n) * math.log2(c / n) for c in Counter(s).values())

def triage_txt_streams(path: str, min_chars: int = 2048, min_ent: float = 4.6) -> list[dict]:
    char_totals: dict[tuple[str, str], int] = defaultdict(int)
    weighted_ent: dict[tuple[str, str], float] = defaultdict(float)
    resp_counts: dict[tuple[str, str], int] = defaultdict(int)

    with open(path, "r", encoding="utf-8") as fh:
        for line in fh:
            if not line.strip():
                continue
            ev = json.loads(line)
            parts = ev.get("qname", "").rstrip(".").lower().split(".")
            if len(parts) < 2:
                continue
            base = ".".join(parts[-2:])
            joined = "".join(ev.get("txt_strings") or [])
            if not joined:
                continue
            key = (ev["client_ip"], base)
            n = len(joined)
            char_totals[key] += n
            weighted_ent[key] += shannon_entropy(joined) * n
            resp_counts[key] += 1

    alerts = []
    for (ip, dom), tot_n in char_totals.items():
        if tot_n < min_chars:
            continue
        avg_ent = weighted_ent[(ip, dom)] / tot_n
        if avg_ent > min_ent:
            alerts.append({
                "client_ip": ip,
                "base_domain": dom,
                "txt_responses": resp_counts[(ip, dom)],
                "total_txt_chars": tot_n,
                "mean_entropy_bits": round(avg_ent, 3),
            })
    return sorted(alerts, key=lambda x: -x["total_txt_chars"])

if __name__ == "__main__":
    print(json.dumps(triage_txt_streams(sys.argv[1]), indent=2))
