from pathlib import Path

def extract_sha256(image_id: str) -> str | None:
    idx = image_id.find("sha256:")
    return image_id[idx:] if idx >= 0 else None

def verify_running_digests(pods_path: str, allow_path: str) -> list[dict]:
    pods = json.loads(Path(pods_path).read_text(encoding="utf-8")).get("items", [])
    allow = json.loads(Path(allow_path).read_text(encoding="utf-8"))
    violations = []

    for pod in pods:
        status = pod.get("status") or {}
        if status.get("phase") != "Running":
            continue
        meta = pod.get("metadata") or {}
        pod_ref = f"{meta.get('namespace', 'default')}/{meta.get('name', 'unknown')}"
        statuses = (status.get("initContainerStatuses") or []) + (status.get("containerStatuses") or [])
        for cs in statuses:
            digest = extract_sha256(cs.get("imageID", ""))
            issues = []
            if not digest:
                issues.append("missing_sha256_digest")
            elif digest not in allow:
                issues.append("unregistered_image_digest")
            else:
                rec = allow[digest]
                if not rec.get("cosign_verified", False):
                    issues.append("cosign_unverified")
                if int(rec.get("critical_vulns", 0)) > 0:
                    issues.append(f"critical_vulns:{rec['critical_vulns']}")
            if issues:
                violations.append({
                    "pod": pod_ref,
                    "container": cs.get("name"),
                    "image": cs.get("image"),
                    "digest": digest,
                    "issues": issues,
                })
    return violations

